import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"屯","description":"周易集解 - 屯","frontmatter":{"title":"屯","description":"周易集解 - 屯"},"headers":[],"relativePath":"classics/jijie/003.md","filePath":"classics/jijie/003.md"}'),l={name:"classics/jijie/003.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="屯" tabindex="-1">屯 <a class="header-anchor" href="#屯" aria-label="Permalink to “屯”">​</a></h1><h2 id="屯-1" tabindex="-1">屯 <a class="header-anchor" href="#屯-1" aria-label="Permalink to “屯”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>屯，元亨利貞。勿用有攸往，利建侯。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：有天地，然後萬物生焉。盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，萬物之始生也。</p><p>崔憬曰：此仲尼序文王次卦之意也。不序乾坤之次者，以一生二，二生三，二生萬物。則天地之次第可知，而萬物之先後宜序也。萬物之始生者，言剛柔始交，故萬物資始於乾，而資生於坤。</p><p>虞翻曰：坎二之初，剛柔交震，故元亨。之初得正，故利貞矣。</p><p>虞翻曰：之外稱往。初震得正，起之慾應，動而失位，故勿用有攸往。震為侯，初剛難拔，故利以建侯。老子曰：善建者，不拔也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：屯，剛柔始交而難生。動乎險中，大亨貞。雷雨之動滿盈，天造草昧。宜建侯而不寧。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：乾剛坤柔，坎二交初，故始交。確乎難拔，故難生也。</p><p>崔憬曰：十二月陽始浸長，而交於陰，故曰剛柔始交。萬物萌芽，生於地中，有寒冰之難，故言難生。於人事，則是運季業初之際也。</p><p>荀爽曰：物難在始生，此本坎卦也。</p><p>案：初六升二，九二降初，是剛柔始交也。交則成震，震為動也，上有坎，是動乎險中也。動則物通而得正。故曰「動乎險中，大亨貞」也。</p><p>荀爽曰：雷震雨潤，則萬物滿盈而生也。</p><p>虞翻曰：震雷坎雨，坤為盈也。謂三已反正，成既濟。坎水流坤，故滿盈。謂雷動雨施，品物流形也。</p><p>荀爽曰：謂陽動在下，造物於冥昧之中也。</p><p>荀爽曰：天地初開，世尚屯難，震位承乾，故宜建侯。動而遇險，故不寧也。</p><p>虞翻曰：造，造生也。草，草創物也。坤冥為昧，故天造草昧。成既濟定，故曰不寧，言寧也。</p><p>乾寶曰：水運將終，木德將始，殷周際也。百姓盈盈，匪君子不寧。天下既遭屯險之難，後王宜盪之以雷雨之政，故封諸侯以寧之也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雲雷，屯。君子以經綸。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：雷雨者，興養萬物。今言屯者，十二月雷伏藏地中，未得動出。雖有雲雨，非時長育，故言屯也。</p><p>荀爽曰：屯難之代，萬事失正。經者，常也。綸者，理也。君子以經綸，不失常道也。</p><p>姚信曰：經，緯也。時在屯難，是天地經綸之日，故君子法之，須經綸艱難也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，盤桓，利居貞，利建侯。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：震起艮止，動乎險中，故盤桓。得正得民，利居貞。謂君子居其室，慎密而不出也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雖盤桓，志行正也。以貴下賤，大得民也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：盤桓者，動而退也。謂陽從二動，而退居初，雖盤桓，得其正也。</p><p>荀爽曰：陽貴而陰賤，陽從二來，是以貴下賤，所以得民也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，屯如邅如，乘馬班加。匪寇婚媾，女子貞不字，十年乃字。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：陽動而止，故屯如也。陰乘於陽，故邅如也，</p><p>虞翻曰：屯邅盤桓，謂初也。震為馬作足，二乘初，故乘馬。班，躓也。馬不進，故班如矣。</p><p>虞翻曰：匪非也。寇謂五。坎為寇盜，應在坎，故匪寇。陰陽德正，故婚媾。字，妊娠也。三失位，變復體離。離為女子，為大腹，故稱字。今失位為坤，離象不見，故女子貞不字。坤數十。三動反正，離女大腹。故十年反常乃字。謂成既濟定也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六二之難，乘剛也。十年乃字，反常也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：下乘初九，故為之難也。</p><p>《九家易》曰：陰出於坤，今還為坤，故曰反常也。陰出於坤，謂乾再索而得坎。今變成震，中有坤體，故言陰出於坤。今還於坤，謂二從初即逆，應五順也。去逆就順，陰陽道正，乃能長養，故曰十年乃字。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，即鹿無虞，惟入於林中，君子幾，不如舍，往吝。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：即，就也。虞謂虞人，掌禽獸者。艮為山，山足稱鹿。鹿，林也。三變體坎，坎為藂木。山下，故稱林中。坤為兕虎；震為麋鹿，又為驚走；艮為狐狼。三變禽走入於林中，故曰「即鹿無虞，惟入於林中」矣。</p><p>虞翻曰：君子謂陽已正位。幾，近。舍，置。吝，疵也。三應於上，之應歷險。不可以往，動如失位。故不如舍之，往必吝窮矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：即鹿無虞，以從禽也。君子舍之，往吝窮也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>案：《白虎通》雲：禽者何？鳥獸之總名，為人所禽制也。即此卦九五爻辭。王用三驅，失前禽，是其義也。</p><p>崔憬曰：君子見動之微，逆知無虞，則不如舍，而往，往則吝窮也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，乘馬班如，求婚媾，往吉，無不利。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：乘，三也。謂三已變，坎為馬，故曰乘馬。馬在險中，故班如也。或說乘初，初為建侯，安得乘之也。</p><p>崔憬曰：屯難之時，勿用攸往。初雖作應，班如不進。既比於五，五來求婚。男求女，往吉，無不利。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：求而往，明也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：之外稱往。體離，故明也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，屯其膏，小貞吉，大貞兇。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：坎雨稱膏。《詩》雲：陰雨膏之，是其義也。</p><p>崔憬曰：得屯難之宜，有膏澤之惠。謂與四為婚媾，施雖未光，小貞之道也，故吉。至於遠求嘉偶，以行大正，赴二之應，冒難攸往，固宜且兇。故曰大貞正也貞兇也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：屯其膏，施未光也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陽陷陰中，故未光也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，乘馬班如，泣血漣如。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：乘，五也。坎為馬，震為行，艮為止，馬行而止，故班如也。</p><p>《九家易》曰：上六乘陽，故班如也。下二四爻雖亦乘陽，皆更得承五，憂解難除。今上無所復承，憂難不解，故泣血漣如也。體坎為血，伏離為目，互艮為手，掩目流血，泣之象也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：泣血漣如，何可長也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂三變時，離為目。坎為血，震為出。血流出目，故泣血漣如。柔乘於剛，故不可長也。</p>',85)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
